/* @lc app=leetcode id=1361 lang=kotlin */ class Solution { fun validateBinaryTreeNodes(n: Int, leftChild: IntArray, rightChild: IntArray): Boolean = (leftChild + rightChild).filter { it >= 0 }.let { ch -> ch.toSet().let { cs -> ch.size == n - 1 && cs.size == ch.size && (0 until n).filter { it !in cs }.let { r -> r.size == 1 && generateSequence(listOf(r[0])) { f -> f.flatMap { listOf(leftChild[it], rightChild[it]) }.filter { it >= 0 }.takeIf { it.isNotEmpty() } }.take(n + 1).flatten().toList().size == n } } } }